function PromoSlider() {
  const [current, setCurrent] = React.useState(0);

  React.useEffect(() => {
    const timer = setInterval(() => {
      setCurrent((prev) => (prev + 1) % sliderBanners.length);
    }, 5000);

    return () => clearInterval(timer);
  }, []);

  const nextSlide = () => {
    setCurrent((prev) => (prev + 1) % sliderBanners.length);
  };

  const prevSlide = () => {
    setCurrent((prev) => (prev - 1 + sliderBanners.length) % sliderBanners.length);
  };

  return (
    <section className="mx-auto max-w-7xl px-5 py-10 md:px-8">

      <div className="relative overflow-hidden rounded-[2.5rem] bg-white shadow-2xl shadow-blue-900/10 ring-1 ring-slate-200">

        <div className="relative aspect-[1920/650] w-full">

          {sliderBanners.map((banner, index) => (
            <img
              key={index}
              src={banner}
              alt={`Banner ${index + 1}`}
              className={`absolute inset-0 h-full w-full object-cover transition-opacity duration-1000 ${
                current === index ? "opacity-100" : "opacity-0"
              }`}
            />
          ))}

        </div>

        <button
          onClick={prevSlide}
          className="absolute right-5 top-1/2 z-20 flex h-12 w-12 -translate-y-1/2 items-center justify-center rounded-full bg-white/80 text-2xl font-black text-[#234b87] shadow-xl backdrop-blur"
        >
          ›
        </button>

        <button
          onClick={nextSlide}
          className="absolute left-5 top-1/2 z-20 flex h-12 w-12 -translate-y-1/2 items-center justify-center rounded-full bg-white/80 text-2xl font-black text-[#234b87] shadow-xl backdrop-blur"
        >
          ‹
        </button>

        <div className="absolute bottom-5 left-1/2 z-20 flex -translate-x-1/2 gap-2">
          {sliderBanners.map((_, index) => (
            <button
              key={index}
              onClick={() => setCurrent(index)}
              className={`h-2.5 rounded-full transition-all duration-300 ${
                current === index
                  ? "w-8 bg-[#ff861c]"
                  : "w-2.5 bg-white/80"
              }`}
            />
          ))}
        </div>

      </div>

    </section>
  );
}



function normalizeArabicText(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[\u064B-\u065F\u0670]/g, "")
    .replace(/ـ/g, "")
    .replace(/[إأآا]/g, "ا")
    .replace(/ة/g, "ه")
    .replace(/ى/g, "ي")
    .replace(/ؤ/g, "و")
    .replace(/ئ/g, "ي")
    .replace(/[\u200f\u200e]/g, "")
    .replace(/ببحي|بوبحي|بوجي|بوبجي|ببجي|pubg|pubg mobile/gi, " pubg ")
    .replace(/فري\s*فاير|فرى\s*فاير|free\s*fire|freefire/gi, " freefire ")
    .replace(/موبايل\s*ليجندز|موبايل\s*ليجند|mobile\s*legends|mlbb/gi, " mobilelegends ")
    .replace(/يمن\s*موبايل|يمن\s*موبيل|يمن\s*مبايل|اعمل\s*موبايل|yemen\s*mobile/gi, " yemenmobile ")
    .replace(/سبافون|سبأفون|sabafon/gi, " sabafon ")
    .replace(/\bيو\b|ام\s*تي\s*ان|mtn/gi, " youmtn ")
    .replace(/واي|y\s*telecom|\by\b/gi, " wai ")
    .replace(/يمن\s*نت|adsl/gi, " yamennet ")
    .replace(/يمن\s*فورجي|yemen\s*4g|4g/gi, " yemen4g ")
    .replace(/عدن\s*نت/gi, " adennet ")
    .replace(/جوجل\s*بلاي|google\s*play/gi, " googleplay ")
    .replace(/بلايستيشن|playstation|psn/gi, " playstation ")
    .replace(/رايزر|ريزر|razer/gi, " razer ")
    .replace(/نتفلكس|netflix/gi, " netflix ")
    .replace(/[^\u0600-\u06FFa-z0-9\s.]/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function buildWhatsAppSupportLink(message) {
  const text = encodeURIComponent(message || "مرحباً، أحتاج مساعدة بخصوص تطبيق أمد باي");
  const separator = BRAND.links.whatsapp?.includes("?") ? "&" : "?";
  return `${BRAND.links.whatsapp}${separator}text=${text}`;
}

